from selenium.webdriver.common.by import By
from taf.selenium.gnb.oam.coam.classical.common.common import LocalBasicPage
from .base_settings import BaseSettings


class GeneralBtsSiteSettings(LocalBasicPage, BaseSettings):
    """
    Implementation class for specific tab page, has to include tow class variable
    "_methods_list" and "_tab_name"
    """
    _methods_list = ['set_bts_name']
    _tab_name = 'General BTS/Site Settings'

    def __init__(self, driver):
        super(GeneralBtsSiteSettings, self).__init__(driver)

    def get_method_list(self):
        return self._methods_list

    def set_bts_name(self, name=None):
        input_xpath = '//label[contains(text(), "BTS name")]/ancestor::wizard-parameter-input//input'
        if name is not None:
            self.insert_text_to_enable_element((By.XPATH, input_xpath), name)
